function oilPaintProcess(data,w,h,opts){
  opts=opts||{};
  var radius=opts.radius!=null?opts.radius:4;
  var levels=opts.levels!=null?opts.levels:20;
  if(radius<0)radius=0; if(levels<2)levels=2;
  var out=new Uint8ClampedArray(data.length);
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var sumR=new Float64Array(levels), sumG=new Float64Array(levels), sumB=new Float64Array(levels), cnts=new Int32Array(levels);
    for(var ny=y-radius;ny<=y+radius;ny++) for(var nx=x-radius;nx<=x+radius;nx++){
      var sx=nx, sy=ny;
      if(sx<0)sx=0; else if(sx>w-1)sx=w-1;
      if(sy<0)sy=0; else if(sy>h-1)sy=h-1;
      var i2=(sy*w+sx)*4;
      var g=(0.299*data[i2]+0.587*data[i2+1]+0.114*data[i2+2])/255*levels;
      var bi=Math.floor(g); if(bi<0)bi=0; else if(bi>=levels)bi=levels-1;
      sumR[bi]+=data[i2]; sumG[bi]+=data[i2+1]; sumB[bi]+=data[i2+2]; cnts[bi]++;
    }
    var best=-1, bc=0;
    for(var b=0;b<levels;b++){ if(cnts[b]>bc){bc=cnts[b];best=b;} }
    var i=(y*w+x)*4;
    if(best>=0&&bc>0){ out[i]=sumR[best]/bc;out[i+1]=sumG[best]/bc;out[i+2]=sumB[best]/bc;out[i+3]=data[i+3]; }
    else { out[i]=data[i];out[i+1]=data[i+1];out[i+2]=data[i+2];out[i+3]=data[i+3]; }
  }
  return out;
}

var EXPORTS={oilPaintProcess:oilPaintProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.OilPaintForgePure = EXPORTS; }
